const require_defaults = require("../utils/defaults.js");
const require_index = require("../useIntersectionObserver/index.js");
let react = require("react");
//#region src/useElementVisibility/index.ts
const useElementVisibility = (target, options = require_defaults.defaultOptions) => {
	const [visible, setVisible] = (0, react.useState)(false);
	const callback = (0, react.useCallback)((entries) => {
		const rect = entries[0].boundingClientRect;
		setVisible(rect.top <= (window.innerHeight || document.documentElement.clientHeight) && rect.left <= (window.innerWidth || document.documentElement.clientWidth) && rect.bottom >= 0 && rect.right >= 0);
	}, []);
	return [visible, require_index.useIntersectionObserver(target, callback, options)];
};
//#endregion
exports.useElementVisibility = useElementVisibility;
